GLOBAL
  fpg_dungeon = 0;
  fnt_hud = 0;
  score = 0;
  salud = 100;
  municion = 40;

BEGIN
  set_mode(m640x480);
  set_fps(60);

  // Carga explícita de sprites FPG y fuentes FNT (DIV Games Studio)
  fpg_dungeon = load_fpg("dungeon.fpg");
  fnt_hud = load_fnt("gothic.fnt");

  // Iniciar motor de Raycasting Modo 8
  start_mode8(0, 0, 25, 0, 0, 0);

