GLOBAL
  fpg_dungeon = 0;
  fnt_hud = 0;
  salud = 100;
  mana = 75;
  score = 0;

BEGIN
  set_mode(m640x480);
  set_fps(60);

  fpg_dungeon = load_fpg("dungeon.fpg");
